  "HR получит напоминание за N дней до истечения срока документа (ежедневно). Включите также «Уведомление для HR о приближающейся дате документа» или оставьте правила включёнными.": "HR hujjat muddati tugashidan N kun oldin eslatma oladi (har kuni). Shuningdek, «HR uchun hujjatning yaqinlashayotgan sanasi haqida bildirishnoma»ni yoqing yoki qoidalarni yoqilgan holda qoldiring.",
