  "LAN-подключение к терминалу. Пароль в форме сохраняется вместе с «Сохранить». Кнопки ниже — только для сверки/смены пароля на самом устройстве.": "Terminalga LAN orqali ulanish. Formadagi parol «Saqlash» bilan birga saqlanadi. Quyidagi tugmalar — faqat qurilmaning o‘zida parolni solishtirish/o‘zgartirish uchun.",
  "Link (telefon/PC) faqat Ulash / reconnect. Otmetkalar: terminal → Web (HttpHost). Yuzlar: Web «Синхронизировать» → ofisda PC office-link": "Link (telefon/PC) faqat Ulash / reconnect. Otmetkalar: terminal → Web (HttpHost). Yuzlar: Web «Sinxronlash» → ofisda PC office-link",
  "MRZ + ПИНФЛ топилди": "MRZ + JShShIR topildi",
