  "OLAP отчёты за период": "Davr uchun OLAP hisobotlari",
  "Office-link установил пароль на терминале и отправил его на сервер. Проверьте пароль и нажмите «Подтвердить привязку» — после этого отметки идут с терминала на Web, а лица — через Web «Синхронизировать» (server → tunnel/LAN → терминал). Link-приложение — первичная настройка; в sync очередь сервер сам пушит.": "Office-link terminalda parol o‘rnatdi va uni serverga yubordi. Parolni tekshiring va «Bog‘lashni tasdiqlash» tugmasini bosing — shundan so‘ng belgilar terminaldan Web’ga, yuzlar esa Web «Sinxronlash» orqali (server → tunnel/LAN → terminal) boradi. Link ilovasi — dastlabki sozlash; sync navbatiga server o‘zi yuboradi.",
  "Ofis tunnel uzildi (502). Tunnelni ochiq qoldiring va «Синхронизировать» ni qayta bosing.": "Ofis tunnel uzildi (502). Tunnelni ochiq qoldiring va «Sinxronlash» ni qayta bosing.",
