  "Управление кадровым составом организации": "Tashkilot xodimlar tarkibini boshqarish",
  "Управление сохранением фото с терминала при отметках. Это не «Загрузка фото» сотрудников — только кадры прихода/ухода/примерного ухода. Если выключить — новые фото не сохраняются; для «Примерный уход» уже сохранённые кадры удаляются сразу (и строки скрываются из общего списка «Отметки»). Срок хранения: по истечении фото удаляются с сервера (0 = без срока).": "Belgilashda terminaldan olingan fotolarni saqlashni boshqarish. Bu xodimlarning «Foto yuklash» bo‘limi emas — faqat kelish/ketish/taxminiy ketish kadrlari. O‘chirilsa — yangi fotolar saqlanmaydi; «Taxminiy ketish» uchun saqlangan kadrlar darhol o‘chiriladi (qatorlar umumiy «Belgilar» ro‘yxatidan yashiriladi). Saqlash muddati: muddat tugagach fotolar serverdan o‘chiriladi (0 = muddatsiz).",
  "Управляются в карточке сотрудника.": "Xodim kartochkasida boshqariladi.",
